logger = logging.getLogger("api.audit")


class AuditLogger:
    """لاگ رویدادهای کسب‌وکار و امنیتی."""

    @staticmethod
    def log(event: str, user=None, request=None, **extra):
        payload = {
            "event": event,
            "user_id": str(user.id) if user and user.is_authenticated else None,
            "username": user.username if user and user.is_authenticated else None,
            "ip": AuditLogger._get_ip(request) if request else None,
            "user_agent": request.headers.get("User-Agent", "")[:200] if request else None,
            **extra,
        }
        logger.info(event, extra=payload)

    @staticmethod
    def _get_ip(request):
        x_forwarded = request.headers.get("X-Forwarded-For")
        if x_forwarded:
            return x_forwarded.split(",")[0].strip()
        return request.META.get("REMOTE_ADDR", "-")


