class SecurityAudit(AuditLogger):
    @staticmethod
    def login_success(user, request):
        AuditLogger.log("security.login.success", user=user, request=request)

    @staticmethod
    def login_failed(username, request):
        AuditLogger.log("security.login.failed", user=None, request=request, attempted_username=username)

    @staticmethod
    def logout(user, request):
        AuditLogger.log("security.logout", user=user, request=request)

    @staticmethod
    def password_changed(user, request):
        AuditLogger.log("security.password.changed", user=user, request=request)

    @staticmethod
    def permission_denied(user, request, resource, action):
        AuditLogger.log(
            "security.permission.denied",
            user=user, request=request,
            resource=resource, action=action,
        )

    @staticmethod
    def suspicious_activity(user, request, reason):
        AuditLogger.log(
            "security.suspicious",
            user=user, request=request, reason=reason,
        )


