class BusinessAudit(AuditLogger):
    @staticmethod
    def order_created(user, request, order_id, total):
        AuditLogger.log(
            "business.order.created",
            user=user, request=request,
            order_id=order_id, total=str(total),
        )

    @staticmethod
    def order_cancelled(user, request, order_id, reason):
        AuditLogger.log(
            "business.order.cancelled",
            user=user, request=request,
            order_id=order_id, reason=reason,
        )

    @staticmethod
    def payment_processed(user, request, payment_id, amount, status):
        AuditLogger.log(
            "business.payment.processed",
            user=user, request=request,
            payment_id=payment_id, amount=str(amount), status=status,
        )

    @staticmethod
    def subscription_changed(user, request, old_tier, new_tier):
        AuditLogger.log(
            "business.subscription.changed",
            user=user, request=request,
            old_tier=old_tier, new_tier=new_tier,
        )

    @staticmethod
    def sensitive_data_accessed(user, request, resource, resource_id):
        AuditLogger.log(
            "business.data.accessed",
            user=user, request=request,
            resource=resource, resource_id=resource_id,
        )

