import time
from common.metrics import REQUEST_COUNT, REQUEST_LATENCY, REQUEST_IN_PROGRESS


class MetricsMiddleware:
    """ثبت متریک برای هر درخواست."""

    IGNORE_PATHS = ["/health/", "/live/", "/ready/", "/metrics"]

    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        if any(request.path.startswith(p) for p in self.IGNORE_PATHS):
            return self.get_response(request)

        endpoint = self._get_endpoint(request)
        method = request.method

        REQUEST_IN_PROGRESS.labels(method=method, endpoint=endpoint).inc()
        start = time.monotonic()

        try:
            response = self.get_response(request)
        except Exception:
            REQUEST_COUNT.labels(method=method, endpoint=endpoint, status="500").inc()
            raise
        finally:
            duration = time.monotonic() - start
            REQUEST_LATENCY.labels(method=method, endpoint=endpoint).observe(duration)
            REQUEST_IN_PROGRESS.labels(method=method, endpoint=endpoint).dec()

        REQUEST_COUNT.labels(
            method=method,
            endpoint=endpoint,
            status=str(response.status_code),
        ).inc()
        return response

    @staticmethod
    def _get_endpoint(request):
        """نام endpoint — بدون UUID."""
        match = getattr(request, "resolver_match", None)
        if match:
            return match.url_name or match.route or request.path
        return request.path

